CREATE DATABASE IF NOT EXISTS pumphouseup CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE pumphouseup;

CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, is_admin BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE products (id INT AUTO_INCREMENT PRIMARY KEY, internal_code VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(180) NOT NULL, description TEXT, unit VARCHAR(20) NOT NULL DEFAULT 'un', stock_quantity DECIMAL(12,3) NOT NULL DEFAULT 0, minimum_stock DECIMAL(12,3) NOT NULL DEFAULT 0, purchase_cost DECIMAL(12,2) NOT NULL DEFAULT 0, sale_price DECIMAL(12,2) NOT NULL DEFAULT 0, desired_margin DECIMAL(7,4) NOT NULL DEFAULT 0, brand VARCHAR(100), model VARCHAR(100), color VARCHAR(60), size VARCHAR(60), storage_location VARCHAR(120), image_path VARCHAR(500), is_active BOOLEAN NOT NULL DEFAULT TRUE, category_id INT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_product_category FOREIGN KEY (category_id) REFERENCES categories(id));
CREATE INDEX ix_products_name ON products(name);
CREATE TABLE stock_movements (id INT AUTO_INCREMENT PRIMARY KEY, product_id INT NOT NULL, movement_type VARCHAR(30) NOT NULL, quantity DECIMAL(12,3) NOT NULL, previous_quantity DECIMAL(12,3) NOT NULL, new_quantity DECIMAL(12,3) NOT NULL, unit_cost DECIMAL(12,2), reason VARCHAR(500), document_number VARCHAR(100), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE sales (id INT AUTO_INCREMENT PRIMARY KEY, total_amount DECIMAL(12,2) NOT NULL DEFAULT 0, total_cost DECIMAL(12,2) NOT NULL DEFAULT 0, payment_method VARCHAR(40) NOT NULL DEFAULT 'pix', notes TEXT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sale_items (id INT AUTO_INCREMENT PRIMARY KEY, sale_id INT NOT NULL, product_id INT NOT NULL, quantity DECIMAL(12,3) NOT NULL, unit_price DECIMAL(12,2) NOT NULL, unit_cost DECIMAL(12,2) NOT NULL, total_amount DECIMAL(12,2) NOT NULL, gross_profit DECIMAL(12,2) NOT NULL, FOREIGN KEY (sale_id) REFERENCES sales(id), FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE financial_transactions (id INT AUTO_INCREMENT PRIMARY KEY, transaction_type VARCHAR(20) NOT NULL, category VARCHAR(100) NOT NULL, description VARCHAR(255) NOT NULL, amount DECIMAL(12,2) NOT NULL, payment_method VARCHAR(40) NOT NULL DEFAULT 'pix', status VARCHAR(20) NOT NULL DEFAULT 'paid', source_type VARCHAR(40), source_id INT, transaction_date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, notes TEXT);
CREATE INDEX ix_financial_date ON financial_transactions(transaction_date);
CREATE TABLE attachments (id INT AUTO_INCREMENT PRIMARY KEY, original_name VARCHAR(255) NOT NULL, stored_path VARCHAR(500) NOT NULL, content_type VARCHAR(120) NOT NULL, file_size INT NOT NULL, entity_type VARCHAR(40), entity_id INT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE system_settings (id INT AUTO_INCREMENT PRIMARY KEY, `key` VARCHAR(80) NOT NULL UNIQUE, `value` VARCHAR(500) NOT NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
